let persistedRaw=null;
const STORAGE='wordorbit.state.v1'; // Deliberately separate from the author's personal app.
const blank=()=>({version:1,books:[],words:[],prog:{},daily:{},mistakes:{},settings:{newPerDay:10,reviewPerDay:30,mode:'auto',soundEffects:true,soundVolume:.4,backgroundMusic:true,musicVolume:.18},theme:null,xp:0,awards:{},lastExport:0});
let state=blank(),view='home',session=null,bookId=null,preview=null,storageFailed=false;
let selectedMistakes=null;
const sounds=createSoundPlayer(()=>({enabled:state.settings.soundEffects!==false,volume:state.settings.soundVolume??.4,theme:state.theme||'space'}));
const music=createMusicPlayer(()=>({enabled:state.settings.backgroundMusic!==false,volume:state.settings.musicVolume??.18,theme:state.theme}));
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={
 orbit:'<ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(-35 12 12)"/><circle cx="12" cy="12" r="5"/>',
 home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',
 book:'<path d="M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2v16"/>',
 flag:'<path d="M5 22V3c5-4 9 4 15 0v10c-6 4-10-4-15 0"/>',
 trophy:'<path d="M7 3h10v6a5 5 0 0 1-10 0zM12 14v6M7 21h10M7 5H3v3a4 4 0 0 0 4 4M17 5h4v3a4 4 0 0 1-4 4"/>',
 chart:'<path d="M4 20V10m8 10V4m8 16v-7M2 21h20"/>',
 settings:'<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',
 star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5"/>',
 download:'<path d="M12 3v13m-5-5 5 5 5-5M3 17v4h18v-4"/>',
 leaf:'<path d="M20 3C8 0 2 8 6 15c5 7 15 2 14-12ZM4 21 16 8"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',
 paw:'<ellipse cx="12" cy="16" rx="6" ry="4"/><ellipse cx="5" cy="9" rx="2" ry="3"/><ellipse cx="10" cy="5" rx="2" ry="3"/><ellipse cx="16" cy="5" rx="2" ry="3"/><ellipse cx="21" cy="10" rx="2" ry="3"/>',
 apple:'<path d="M12 7c-9-7-15 7-6 14 3 2 4-1 6-1s3 3 6 1c9-7 3-21-6-14ZM12 7c0-5 5-6 7-5-1 4-4 5-7 5Z"/>',
 planet:'<circle cx="12" cy="12" r="7"/><path d="M5 7C-7 19 5 24 21 7c7-8-1-9-3-7"/>',
 palette:'<path d="M12 2a10 10 0 1 0 0 20c5 0 1-5 4-6 8 0 8-14-4-14Z"/><circle cx="7" cy="8" r="1"/><circle cx="13" cy="6" r="1"/><circle cx="18" cy="10" r="1"/>',
 flame:'<path d="M13 2c2 7-5 7-2 12 2-1 4-3 4-5 10 9 2 17-5 13C-1 17 9 8 13 2Z"/>',
 check:'<path d="m5 12 4 4L20 5"/>',
 music:'<path d="M9 18V5l12-2v13M9 8l12-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="18" cy="16" rx="3" ry="2"/>',
 sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
 close:'<path d="m5 5 14 14M5 19 19 5"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',
 refresh:'<path d="M21 9A9 9 0 1 0 20 17M21 2v7h-7"/>',
 bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8z"/>',
 plus:'<path d="M12 4v16M4 12h16"/>',
};
function ico(name,cls=''){return `<svg class="ico ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.star}</svg>`;}
const theme=()=>THEMES[state.theme]||THEMES.space;
function load(){try{const raw=localStorage.getItem(STORAGE),saved=JSON.parse(raw||'null');if(saved&&!validBackup(saved))throw Error('Invalid stored backup');persistedRaw=raw;state=saved?{...blank(),...saved,settings:{...blank().settings,...saved.settings}}:blank();if(!THEMES[state.theme])state.theme=null;}catch{storageFailed=true;}}
function syncExternal(){try{if(!storageChanged(persistedRaw,localStorage.getItem(STORAGE)))return false;session=null;view='home';selectedMistakes=null;load();render();toast('另一个页面更新了学习记录，已载入最新进度。请重新开始本轮。');return true;}catch{return false;}}
function save(){if(syncExternal())return false;try{const raw=JSON.stringify(state);localStorage.setItem(STORAGE,raw);persistedRaw=raw;return true;}catch{storageFailed=true;toast('本机存储不可用或已满，请导出备份后继续。');return false;}}
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
function applyTheme(){document.documentElement.dataset.theme=state.theme||'space';document.querySelector('meta[name="theme-color"]').content=theme().background;}
function starsArt(cute=false){return `<svg viewBox="0 0 540 360" class="world-art" role="img" aria-label="${cute?'云朵上的单词小岛':'飞船飞过紫色星球'}">
<defs><linearGradient id="${cute?'island-planet':'space-planet'}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${cute?'#c2ead5':'#beb1fc'}"/><stop offset="1" stop-color="${cute?'#6cac92':'#6354ab'}"/></linearGradient><linearGradient id="ship" x2="1" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#c6cfdf"/></linearGradient></defs>
${cute?'<ellipse cx="275" cy="300" rx="180" ry="26" fill="#c3dcd0" opacity=".4"/><path d="M90 238Q30 230 65 206q-5-40 41-33 15-39 47-15 38-8 44 30 48 29-10 48Z" fill="white" opacity=".8"/><path d="M365 117q-20-36 15-40 8-30 35-14 42-8 41 26 29 18 1 30Z" fill="white"/>':'<ellipse cx="280" cy="294" rx="165" ry="23" fill="#6652b5" opacity=".13"/>'}
<g fill="${cute?'#e1b36c':'#cec9ed'}"><circle cx="91" cy="88" r="2"/><circle cx="444" cy="214" r="3"/><circle cx="352" cy="39" r="2"/><circle cx="164" cy="285" r="2"/><path d="m420 57 2 8 8 2-8 2-2 8-2-8-8-2 8-2ZM82 253l2 6 6 2-6 2-2 6-2-6-6-2 6-2Z"/></g>
<ellipse cx="283" cy="207" rx="155" ry="45" transform="rotate(-25 283 207)" fill="none" stroke="${cute?'#eacb91':'#9b8cda'}" stroke-width="17" opacity=".5"/>
<circle cx="283" cy="207" r="91" fill="url(#${cute?'island-planet':'space-planet'})"/><path d="M217 172q56-35 136 3M202 207q69-30 164 6M215 244q70-19 133 15" fill="none" stroke="${cute?'#a7d3b6':'#b1a4e3'}" stroke-width="13" opacity=".35"/>
<ellipse cx="283" cy="207" rx="155" ry="45" transform="rotate(-25 283 207)" fill="none" stroke="${cute?'#e7bd77':'#c6b7ef'}" stroke-width="10" stroke-dasharray="245 420"/>
${cute?'<path d="M247 123q-17-48 9-52 18-1 19 41m22-3q3-56 24-46 23 10-4 58" fill="#f6eee2" stroke="#e6d9c7" stroke-width="3"/><ellipse cx="286" cy="134" rx="43" ry="35" fill="#fff8ee"/><circle cx="272" cy="133" r="3" fill="#4f655b"/><circle cx="299" cy="133" r="3" fill="#4f655b"/><path d="m282 144 5 3 5-3" fill="none" stroke="#b58b80" stroke-width="2"/><ellipse cx="263" cy="143" rx="7" ry="4" fill="#ecc1b2"/><ellipse cx="309" cy="143" rx="7" ry="4" fill="#ecc1b2"/>':`<g transform="translate(179 100) rotate(35)"><path d="M-13 42-22 73 0 61l22 12-9-31" fill="#9e91df"/><path d="M-8 68 0 96 8 68" fill="#f4cc8d"/><path d="M0-25C-31 5-22 43-13 64h26C22 43 31 5 0-25Z" fill="url(#ship)"/><circle cy="17" r="11" fill="#6668a6" stroke="#dddafa" stroke-width="4"/><path d="M0-25Q-10-13-14-1h28Q10-13 0-25" fill="#a796ed"/></g>`}
<circle cx="426" cy="273" r="16" fill="${cute?'#f2cd8c':'#e9bc88'}"/><circle cx="105" cy="151" r="7" fill="${cute?'#8fc3b0':'#8d9ec5'}"/></svg>`;}

function onboarding(){applyTheme();$('#app').className='onboarding';$('#app').innerHTML=`<header class="welcome-brand">${ico('orbit')}<b>Word Orbit</b><span>单词探索站</span></header><main class="welcome"><span class="eyebrow">YOUR WORDS. YOUR WORLD.</span><h1>选一个世界，<br>开始你的单词探险。</h1><p>同样的成长，不一样的风景。选你喜欢的，随时都能换。</p><div class="theme-cards">${Object.values(THEMES).map(t=>`<button class="theme-card ${t.id}" data-act="theme" data-theme="${t.id}"><div class="theme-picture">${starsArt(t.id==='island')}</div><div class="theme-card-body"><span class="eyebrow">${t.tag}</span><h2>${t.name} ${ico('arrow')}</h2><p>${t.description}</p><span class="theme-choose">进入这个世界 ${ico('arrow')}</span></div></button>`).join('')}</div><div class="future-note">${ico('palette')} 更多个性化世界，留给未来的你。<span>无需注册 · 进度保存在当前浏览器</span></div></main><footer class="welcome-footer">一点点记住，一点点走远。<span>MADE FOR CURIOUS MINDS</span></footer>`;}
const navs=[['home','home','探索首页'],['books','book','我的词库'],['challenge','flag','趣味闯关'],['mistakes','refresh','错题本'],['rewards','trophy','成长徽章'],['stats','chart','学习足迹']];
function render(){
 applyTheme();music.sync();if(!state.theme){onboarding();return;}
 const t=theme(),s=summarize(state),xp=state.xp||0;
 $('#app').className='shell';$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-act="nav" data-view="home"><span class="brand-symbol">${ico('orbit')}</span><span><b>Word Orbit<span class="brand-dot">.</span></b><small>单词探索站</small></span></a><div class="side-caption">我的探索空间</div><nav>${navs.map(([id,icon,label])=>`<button data-act="nav" data-view="${id}" class="nav-item ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${ico(icon)}<span>${label}</span>${id==='books'?`<small>${state.books.length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-card"><span class="local-dot"></span>本机专属空间<p>不用账号，打开就能学。<br>记得备份你的探索记录。</p></div><button class="nav-item ${view==='settings'?'active':''}" data-act="nav" data-view="settings">${ico('settings')}<span>偏好与备份</span></button><div class="side-footer">LEARN A LITTLE. GO A LITTLE FURTHER.</div></div></aside>
 <div class="workspace"><header class="topbar"><div class="breadcrumb">我的空间 <span>/</span> <b>${navs.find(n=>n[0]===view)?.[2]||'偏好与备份'}</b></div><div class="top-actions"><div class="theme-switch" role="group" aria-label="切换风格">${Object.values(THEMES).map(a=>`<button data-act="theme" data-theme="${a.id}" class="${a.id===state.theme?'selected':''}" aria-pressed="${a.id===state.theme}">${ico(a.icon)}<span>${a.name}</span></button>`).join('')}</div><button class="music-toggle ${state.settings.backgroundMusic!==false?'enabled':''}" data-act="music-toggle" aria-label="背景音乐开关" aria-pressed="${state.settings.backgroundMusic!==false}" title="背景音乐${state.settings.backgroundMusic!==false?'已开启':'已关闭'}">${ico('music')}</button><span class="xp-pill">${ico('star')} ${xp}</span><button class="avatar" title="偏好与备份" aria-label="打开偏好与备份" data-act="nav" data-view="settings">${ico(state.theme==='space'?'orbit':'leaf')}</button></div></header><main id="main"></main><footer class="page-footer"><span>${ico('lock')} 词库与进度仅保存在当前浏览器</span><span>Word Orbit · 每一点进步都算数</span></footer></div>`;
 const main=$('#main');if(session){renderSession(main);return;}
 if(view==='home')renderHome(main,s);else if(view==='books')renderBooks(main);else if(view==='book')renderBook(main);else if(view==='challenge')renderChallenges(main);else if(view==='mistakes')renderMistakes(main);else if(view==='rewards')renderRewards(main,s);else if(view==='stats')renderStats(main,s);else renderSettings(main);
 if(storageFailed)toast('浏览器存储不可用。请先导出备份，避免关闭后丢失。');
}
function pageHeading(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function bookCard(b){const isPreset=!!b.words&&!b.bookId;const ws=isPreset?b.words:state.words.filter(w=>w.bookId===b.id);const learned=isPreset?ws.filter(w=>state.prog[wordKey(w[0])]).length:ws.filter(w=>state.prog[wordKey(w.word)]).length;return `<button class="book-card" data-act="${isPreset?'preset':'book'}" data-id="${b.id}"><div class="book-cover ${b.color||'purple'}">${ico(b.icon||'book')}<span>${isPreset?'WORD COLLECTION':'MY COLLECTION'}</span><i>W<span>o</span>rd.</i></div><div class="book-info"><span class="book-tag">${isPreset?b.level:'我的词库'}</span><h3>${esc(b.name)}</h3><p>${ws.length} 个单词 <span>·</span> ${isPreset?esc(b.subtitle):`已学习 ${learned} 个`}</p><div class="mini-progress"><i style="width:${ws.length?learned/ws.length*100:0}%"></i></div></div><span class="book-arrow">${ico('arrow')}</span></button>`;}
function renderHome(main,s){const t=theme(),q=buildQueue(state),done=s.today.newN,goal=state.settings.newPerDay||0,pct=goal?Math.min(100,done/goal*100):0,learned=Object.keys(state.prog).length,hasWords=state.words.length>0;
 main.innerHTML=`${pageHeading('A LITTLE PROGRESS, EVERY DAY',t.greeting,'不必一口气记住所有。今天，先向前一小步。',`<span class="date-chip">${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span>`)}
 <div class="dashboard"><section class="main-column"><div class="hero-panel"><div class="hero-copy"><div class="hero-badge"><span></span> ${t.location} · DAY ${Object.keys(state.daily).filter(k=>state.daily[k].totalN>0).length+1}</div><h2>${t.hero.split('\n').join('<br>')}</h2><p>${hasWords?`你的航线里有 ${s.total} 个单词，今天再认识几个吧。`:'从熟悉的生活出发，发现单词里的大千世界。'}</p><button class="button primary" data-act="${hasWords?'start':'preset-start'}" data-id="everyday">${hasWords?'开始今日探索':'开启第一次探索'} ${ico('arrow')}</button><span class="hero-footnote">${hasWords?`${q.news.length} 个新词 · ${q.reviews.length} 个待复习`:'每次 10 个词 · 约 5 分钟'}</span></div><div class="hero-visual">${starsArt(state.theme==='island')}<span class="art-label">${ico('star')} 每个单词，都是新的发现</span></div></div>
 <div class="section-title"><h2>今天，想怎么学？</h2><span>按你的节奏来</span></div><div class="mode-grid"><button class="mode-card" data-act="quick" data-mode="card"><span class="mode-icon purple">${ico('book')}</span><h3>单词闪卡</h3><p>翻一翻，认识新朋友</p><span class="mode-footer">轻松记忆 ${ico('arrow')}</span></button><button class="mode-card" data-act="quick" data-mode="choice"><span class="mode-icon peach">${ico('bolt')}</span><h3>选择挑战</h3><p>选一选，看看记住多少</p><span class="mode-footer">检验记忆 ${ico('arrow')}</span></button><button class="mode-card" data-act="quick" data-mode="spell"><span class="mode-icon mint">${ico('flag')}</span><h3>拼写任务</h3><p>拼一拼，让记忆更牢固</p><span class="mode-footer">进阶练习 ${ico('arrow')}</span></button></div>
 <div class="section-title"><h2>${state.books.length?'继续你的单词收藏':'从这些单词开始'}</h2><button class="text-button" data-act="nav" data-view="books">全部词库 ${ico('arrow')}</button></div><div class="book-grid">${(state.books.length?state.books.slice(0,2):PRESETS.slice(0,2)).map(bookCard).join('')}</div><div class="import-strip"><div class="import-icon">${ico('upload')}</div><div><b>你的单词，也能成为探险地图。</b><p>上传老师的单词表，定制属于自己的练习。</p></div><button class="button secondary" data-act="upload">导入词库 ${ico('plus')}</button></div></section>
 <aside class="right-column"><section class="goal-card"><div class="section-title"><h3>今日小目标</h3>${ico('sun')}</div><div class="goal-ring" style="--pct:${pct}%"><div><b>${done}<small> / ${goal}</small></b><span>个新词已探索</span></div></div><p>${goal===0?'今天专注复习，也很棒。':done>=goal?'今日目标达成，做得漂亮！':'每天一点点，进步看得见。'}</p><div class="goal-info"><span>连续探索</span><b>${ico('flame')} ${s.streak} 天</b></div></section><section class="level-card"><div class="level-emblem">${ico('orbit')}</div><div><span>LV.${Math.floor((state.xp||0)/100)+1} 探索者</span><h3>${t.partner}</h3></div><div class="level-progress"><i style="width:${(state.xp||0)%100}%"></i></div><div class="level-meta"><span>${(state.xp||0)%100} / 100 ${t.currency}</span><span>下一级 ${ico('arrow')}</span></div></section><section class="tiny-stats"><div><span>已探索单词</span><b>${learned}<small> 个</small></b></div><div><span>已掌握单词</span><b>${s.mastered}<small> 个</small></b></div></section><section class="tip-card"><span class="eyebrow">LITTLE TIP</span><h3>读出来，更容易记住。</h3><p>点一下单词旁边的小喇叭，跟着读一遍，给记忆多一个线索。</p><span class="tip-flower">✳</span></section></aside></div>`;
}
function renderBooks(main){const textbooks=PRESETS.filter(p=>p.category==='textbook'),themes=PRESETS.filter(p=>p.category!=='textbook');main.innerHTML=`${pageHeading('YOUR WORD COLLECTION','把世界，装进词库。','选择课本开始练习，也可以导入你的课堂单词。',`<button class="button primary" data-act="upload">${ico('upload')} 导入词库</button>`)}<div class="section-title"><h2>我的词库 <small>${state.books.length}</small></h2><button class="text-button" data-act="new">${ico('plus')} 粘贴新词库</button></div>${state.books.length?`<div class="book-grid library-grid">${state.books.map(bookCard).join('')}</div>`:`<div class="empty-panel">${ico('book')}<h3>第一本收藏，从这里开始。</h3><p>选择下面的教材词库，或上传你自己的单词表。</p></div>`}<div class="section-title"><h2>人教 PEP 教材词库 <small>${textbooks.length} 册</small></h2><span>按年级与上下册整理 · 添加后本机保存</span></div><div class="book-grid library-grid textbook-grid">${textbooks.map(bookCard).join('')}</div><p class="textbook-note">六年级下册的新版词汇原页尚未提供，补齐后再加入。</p><div class="section-title"><h2>趣味主题词库</h2><span>生活、动物与宇宙，自由探索</span></div><div class="book-grid library-grid">${themes.map(bookCard).join('')}</div><div class="import-strip"><div class="import-icon">${ico('download')}</div><div><b>第一次整理单词表？</b><p>下载模板，在 Excel 中填写后直接上传。</p></div><button class="button secondary" data-act="template">下载模板</button></div>`;}

function renderBook(main){const b=state.books.find(x=>x.id===bookId);if(!b){view='books';render();return;}const ws=state.words.filter(w=>w.bookId===b.id);main.innerHTML=`${pageHeading('MY COLLECTION',esc(b.name),`${ws.length} 个单词 · 练习时优先选择本词库`, `<button class="button primary" data-act="book-start" data-id="${b.id}">开始学习 ${ico('arrow')}</button>`)}<div class="book-toolbar"><button class="text-button" data-act="nav" data-view="books">← 返回词库</button><button class="text-button" data-act="rename" data-id="${b.id}">重命名</button><button class="text-button danger-text" data-act="delete" data-id="${b.id}">删除词库</button></div><section class="panel word-list"><div class="word-row list-head"><span>单词 / 点击发音</span><span>中文释义</span><span>学习状态</span></div>${ws.map(w=>{const p=state.prog[wordKey(w.word)];return `<div class="word-row"><button class="word-speak" data-act="speak" data-word="${esc(w.word)}">${esc(w.word)} ${ico('sound')}</button><span>${esc(w.meaning)}</span><span class="status ${p?'learned':''}">${!p?'未探索':p.stage>=4?'已掌握':'学习中'}</span></div>`;}).join('')}</section>`;}

function addPreset(id){const p=PRESETS.find(x=>x.id===id);if(!p)return null;let b=state.books.find(x=>x.presetId===id);if(b)return b.id;b={id:uid('b'),name:p.name,presetId:p.id,color:p.color,icon:p.icon,on:true};state.books.push(b);for(const row of (p.rows||p.words.map(([word,meaning])=>({word,meaning}))))state.words.push({...row,id:uid('w'),bookId:b.id,pos:'',phonetic:''});save();return b.id;}
function showPreset(id){const p=PRESETS.find(x=>x.id===id);if(!p)return;modal(`<span class="eyebrow">WORD COLLECTION</span><h2>${p.name}</h2><p>${p.words.length} 个单词 · ${p.subtitle}</p><div class="preset-preview">${p.words.map(([w,m])=>`<span><b>${esc(w)}</b>${esc(m)}</span>`).join('')}</div><button class="button primary full" data-act="preset-add" data-id="${id}">添加到我的词库 ${ico('plus')}</button>`);}
function renderChallenges(main){main.innerHTML=`${pageHeading('PLAY. REMEMBER. REPEAT.','给记忆一点挑战。','同一份词库，三种不同的玩法。每轮最多 10 个新词或到期词。')}<div class="challenge-grid">${[['card','book','01','闪卡热身','先想一想，再翻开答案。适合认识新词。'],['choice','bolt','02','选择挑战','从候选释义中找到正确答案。'],['spell','flag','03','拼写任务','看中文，试着拼出完整的英文。']].map(([m,i,n,title,desc])=>`<section class="panel challenge-card"><span class="challenge-number">${n}</span><div class="mode-icon ${m==='card'?'purple':m==='choice'?'peach':'mint'}">${ico(i)}</div><h2>${title}</h2><p>${desc}</p><button class="button secondary full" data-act="quick" data-mode="${m}">开始挑战 ${ico('arrow')}</button></section>`).join('')}</div><div class="import-strip"><div><b>错词，值得再挑战一次。</b><p>去错题本选词改正，答对 3 次就移出。</p></div><button class="button secondary" data-act="nav" data-view="mistakes">打开错题本 ${ico('refresh')}</button></div><div class="notice">${ico('star')} 每个单词每天首次认真作答获得 2 点奖励，答对或自评认识再获 3 点；复刷不重复加分。</div>`;}
function activePool(book=null){const byWord=new Map();for(const w of state.words){if(book&&w.bookId!==book)continue;const key=wordKey(w.word),entry=byWord.get(key);if(entry){if(!entry.meanings.includes(w.meaning))entry.meanings.push(w.meaning);}else byWord.set(key,{...w,key,meanings:[w.meaning]});}return [...byWord.values()].map(({meanings,...w})=>({...w,meaning:meanings.join(' / ')}));}
function start(mode=null,book=null){if(!state.words.length){addPreset('everyday');}let available=activePool(book);const today=state.daily[dayKey()]||{},freshLimit=Math.max(0,state.settings.newPerDay-(today.newN||0)),reviewLimit=Math.max(0,state.settings.reviewPerDay-(today.revN||0));const due=available.filter(w=>state.prog[w.key]&&state.prog[w.key].due<=Date.now()).sort((a,b)=>state.prog[a.key].due-state.prog[b.key].due).slice(0,reviewLimit);const fresh=shuffle(available.filter(w=>!state.prog[w.key])).slice(0,freshLimit);let items=[...due,...fresh].slice(0,10),practice=false;if(!items.length){items=shuffle(available).slice(0,10);practice=true;}if(!items.length){toast('这个词库还没有单词，请先导入。');return;}session={items,pool:available,index:0,mode,phase:'q',revealed:false,stats:{correct:0,total:0,xp:0},practice,book};render();}
function mistakeEntries(){return Object.entries(state.mistakes).filter(([,entry])=>entry.active).sort((a,b)=>b[1].lastAt-a[1].lastAt);}
function renderMistakes(main){
 const entries=mistakeEntries(),keys=new Set(entries.map(([key])=>key));
 if(selectedMistakes===null)selectedMistakes=new Set(keys);
 selectedMistakes=new Set([...selectedMistakes].filter(key=>keys.has(key)));
 const cleared=Object.values(state.mistakes).reduce((sum,r)=>sum+r.cleared,0);
 main.innerHTML=`${pageHeading('TRY AGAIN. GROW STRONGER.','把错题，变成你的拿手题。','答错自动收录。勾选单词闯关，每词答对 3 次就移出；中途答错，计数归零。')}<section class="panel mistake-overview"><div><b>${entries.length}</b><span>待改正单词</span></div><div><b>${cleared}</b><span>累计改正完成</span></div><p>改正进度自动保存，可分几次完成。移出的词再次答错，会重新进入错题本。</p></section>${entries.length?`<section class="panel"><div class="mistake-toolbar"><div><button class="text-button" data-act="mistakes-all">全选</button><button class="text-button" data-act="mistakes-none">取消全选</button><span>已选 ${selectedMistakes.size} 个</span></div><div class="mistake-actions"><button class="button secondary" data-act="mistakes-start" data-mode="choice" ${selectedMistakes.size?'':'disabled'}>选择题闯关</button><button class="button primary" data-act="mistakes-start" data-mode="spell" ${selectedMistakes.size?'':'disabled'}>拼写改正 ${ico('arrow')}</button></div></div><div class="mistake-list">${entries.map(([key,r])=>`<div class="mistake-row"><label class="mistake-select"><input type="checkbox" data-mistake-key="${esc(key)}" ${selectedMistakes.has(key)?'checked':''} aria-label="选择 ${esc(r.word)}"><span><b>${esc(r.word)}</b><small>${esc(r.meaning)}</small></span></label><button class="text-button" data-act="speak" data-word="${esc(r.word)}" aria-label="朗读 ${esc(r.word)}">${ico('sound')}</button><div class="mistake-count"><b>${r.correct} / 3</b><span>改正答对次数</span><small>累计答错 ${r.wrongCount} 次</small></div></div>`).join('')}</div></section>`:`<section class="panel empty-panel">${ico('check')}<h3>这里暂时没有待改正的词。</h3><p>去学习或挑战吧，遇到的错词会自动收录到这里。</p><button class="button secondary" data-act="nav" data-view="challenge">去趣味闯关 ${ico('arrow')}</button></section>`}`;
}
function startCorrections(mode='spell'){
 const entries=mistakeEntries().filter(([key])=>selectedMistakes?.has(key));
 if(!entries.length){view='mistakes';render();toast(mistakeEntries().length?'先选几个想改正的单词吧。':'所选错词已全部改正，去迎接新的挑战吧！');return;}
 const byKey=new Map(activePool().map(w=>[w.key,w]));
 // Snapshot meanings stay consistent with the notebook even if its library changed.
 for(const [key,r] of mistakeEntries())byKey.set(key,{key,word:r.word,meaning:r.meaning});
 const pool=[...byKey.values()];
 if(mode==='choice'&&new Set(pool.map(w=>w.meaning)).size<2){toast('可选释义太少，已为你切换成拼写改正。');mode='spell';}
 const items=shuffle(entries.map(([key,r])=>({key,word:r.word,meaning:r.meaning})));
 session={items,pool,index:0,mode,phase:'q',revealed:false,stats:{correct:0,total:0,xp:0,cleared:0},practice:true,correction:true};
 view='mistakes';render();window.scrollTo(0,0);
}
function current(){return session?.items[session.index];}
function renderSession(main){const ss=session;if(ss.index>=ss.items.length){main.innerHTML=`<div class="session-wrap"><section class="panel session-summary"><div class="summary-emblem">${ico('trophy')}</div><span class="eyebrow">MISSION COMPLETE</span><h1>${ss.correction?'错题改正，又前进了一步。':'这一步，走得漂亮。'}</h1><p>${ss.correction?`完成 ${ss.stats.total} 次改正练习，${ss.stats.cleared} 个词已答对 3 次并移出。尚未完成的计数会继续保留。`:`你完成了 ${ss.stats.total} 次练习。休息一下，也让记忆沉淀一下。`}</p><div class="summary-stats"><div><b>${ss.stats.correct}</b><span>答对 / 认识</span></div><div><b>+${ss.stats.xp}</b><span>${theme().currency}</span></div><div><b>${ss.stats.total?Math.round(ss.stats.correct/ss.stats.total*100):0}%</b><span>本轮正确率</span></div></div><button class="button primary" data-act="finish">${ss.correction?'返回错题本':'返回探索首页'} ${ico('arrow')}</button><button class="text-button" data-act="again">再练一轮</button></section></div>`;return;}
 const w=current(),p=state.prog[w.key],mode=ss.mode||(p?.stage>=4?'spell':p?.stage>=2?'choice':'card');ss.currentMode=mode;if(mode==='choice'&&!w.options)w.options=buildChoices(w,ss.pool).options;
 const answered=ss.phase==='a';let content='';
 if(mode==='card')content=`<button class="word-speak large-word" data-act="speak" data-word="${esc(w.word)}">${esc(w.word)} ${ico('sound')}</button><span class="question-hint">试着回想一下，它是什么意思？</span>${ss.revealed?`<h2 class="answer-meaning">${esc(w.meaning)}</h2><div class="rating"><button class="button rate-forgot" data-act="answer" data-result="forgot">还不认识<small>稍后再练</small></button><button class="button rate-fuzzy" data-act="answer" data-result="fuzzy">有点印象<small>明天复习</small></button><button class="button rate-know" data-act="answer" data-result="know">我认识！<small>记忆更进一步</small></button></div>`:`<button class="button primary" data-act="reveal">翻开答案 ${ico('refresh')}</button>`}`;
 else if(mode==='choice')content=`<button class="word-speak large-word" data-act="speak" data-word="${esc(w.word)}">${esc(w.word)} ${ico('sound')}</button><p class="question-hint">选出正确的中文释义${w.options.length<4?' · 当前词库候选词较少':''}</p><div class="answer-options">${w.options.map((o,i)=>`<button class="answer-option ${answered?(o===w.meaning?'correct':ss.chosen===i?'incorrect':''):''}" data-act="choice" data-index="${i}" ${answered?'disabled':''}><span>${i+1}</span>${esc(o)}${answered&&o===w.meaning?ico('check'):''}</button>`).join('')}</div>`;
 else content=`<div class="spell-meaning">${esc(w.meaning)}</div><p class="question-hint">把你记住的英文拼出来。提示：${esc(spellHint(w.word))}</p><form id="spellForm"><input id="spelling" aria-label="英文拼写，使用下方字母键盘或电脑键盘" readonly inputmode="none" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" placeholder="点击下方字母拼写…" ${answered?'disabled':''} value="${esc(ss.input||'')}">${!answered?'<button class="button primary" type="submit">确认答案</button>':''}</form>${!answered?`${spellingKeyboard()}<button class="text-button" data-act="giveup">还想不起来，看看答案</button>`:`<p class="spell-correction">正确拼写：<button class="word-speak" data-act="speak" data-word="${esc(w.word)}">${esc(w.word)} ${ico('sound')}</button></p>`}`;
 main.innerHTML=`<div class="session-wrap"><div class="session-top"><button class="text-button" data-act="exit">${ico('close')} 结束本轮</button><span>${ss.correction?'错词闯关 · 每词答对 3 次移出':ss.practice?'自由巩固 · 不改变复习计划':'今日探索'} · ${ss.index+1} / ${ss.items.length}</span><span class="xp-pill">${ico('star')} +${ss.stats.xp}</span></div><div class="session-progress"><i style="width:${ss.index/ss.items.length*100}%"></i></div><section class="panel question">${ss.correction?`<p class="correction-progress" role="status">${state.mistakes[w.key]?.active?`改正进度 ${state.mistakes[w.key].correct} / 3${answered&&ss.result!=='know'?' · 答错后重新累计':''}`:'已答对 3 次，移出错题本！'}</p>`:''}<span class="eyebrow">${{card:'MEET A NEW WORD',choice:'CHOOSE YOUR ANSWER',spell:'SPELL IT OUT'}[mode]}</span>${content}${answered?`<div class="answer-feedback ${ss.result==='know'?'positive':''}">${ss.result==='know'?'记住了，继续前进！':'没关系，再看一眼，下一次会更熟悉。'}</div><button class="button primary" data-act="next">下一个 ${ico('arrow')}</button>`:''}</section><p class="session-note">${ico('lock')} 每次作答自动保存 · 奖励每天按单词去重</p></div>`;
 if(mode==='spell'&&!answered)$('#spelling')?.focus();
}
function answer(result){if(syncExternal()||!session||session.phase!=='q')return;const ss=session,w=current(),prev=state.prog[w.key],isNew=!prev,dk=dayKey();ss.phase='a';ss.result=result;ss.stats.total++;if(result==='know')ss.stats.correct++;
 if(!ss.practice)state.prog[w.key]=schedule(prev,result);
 const wasActive=state.mistakes[w.key]?.active;
 if(result!=='fuzzy')state.mistakes=recordMistake(state.mistakes,w,result==='know',ss.correction===true);
 if(ss.correction&&wasActive&&!state.mistakes[w.key]?.active)ss.stats.cleared++;
 const d=state.daily[dk]||(state.daily[dk]={newN:0,revN:0,okN:0,totalN:0});d.totalN++;if(result==='know')d.okN++;if(!ss.practice){if(isNew)d.newN++;else d.revN++;}
 const rewardKey=`${dk}|${w.key}`;let gain=0;if(!state.awards[rewardKey]){gain=result==='know'?5:2;state.awards[rewardKey]=gain;state.xp+=gain;}ss.stats.xp+=gain;
 // Retry a missed word once, after other words, without an endless loop.
 if(result==='forgot'&&!w.retry&&!ss.correction)ss.items.push({...w,retry:true,options:undefined});
 if(save()){sounds.play(result==='know'?'correct':result==='fuzzy'?'gentle':'wrong');render();}
}
function next(){if(!session||session.phase!=='a')return;session.index++;session.phase='q';session.revealed=false;session.input='';session.chosen=null;if(session.index>=session.items.length)sounds.play('complete',.18);render();}

function spellingKeyboard(){return `<div class="spelling-keyboard" role="group" aria-label="英文拼写键盘">${['qwertyuiop','asdfghjkl','zxcvbnm'].map(row=>`<div class="keyboard-row">${[...row].map(letter=>`<button class="letter-key" type="button" data-act="spell-key" data-key="${letter}" aria-label="字母 ${letter}">${letter}</button>`).join('')}</div>`).join('')}<div class="keyboard-row keyboard-tools"><button class="letter-key" type="button" data-act="spell-key" data-key="-" aria-label="连字符">-</button><button class="letter-key" type="button" data-act="spell-key" data-key="'" aria-label="英文撇号">'</button><button class="letter-key space-key" type="button" data-act="spell-key" data-key=" " aria-label="空格">空格</button><button class="letter-key erase-key" type="button" data-act="spell-key" data-key="Backspace" aria-label="删除最后一个字母">⌫</button></div><p>也可以用电脑键盘输入 · Enter 提交</p></div>`;}
function editSpelling(key){if(syncExternal()||!session||session.phase!=='q'||session.currentMode!=='spell')return;let text=session.input||'';if(key==='Backspace'){if(!text)return;text=text.slice(0,-1);sounds.play('erase');}else if(/^[a-z '-]$/i.test(key)){if(text.length>=64)return;text+=key.toLowerCase();sounds.play(key===' '?'space':'type');}else return;session.input=text;const input=$('#spelling');if(input){input.value=text;input.scrollLeft=input.scrollWidth;}}

function renderRewards(main,s){const vals=achievementValues(state,s),unlockedN=REWARDS.filter(r=>vals[r.kind]>=r.need).length;main.innerHTML=`${pageHeading('SMALL STEPS. REAL ACHIEVEMENTS.','每一点进步，都值得收藏。',`已点亮 ${unlockedN} / ${REWARDS.length} 枚徽章。短期有收获，长期有挑战；两种风格共用成长记录。`)}<section class="panel reward-banner"><div class="level-emblem">${ico('star')}</div><div><span>累计${theme().currency}</span><h2>${state.xp||0} <small>· LV.${Math.floor((state.xp||0)/100)+1}</small></h2></div><p>每天坚持一小步，<br>把好奇心变成你的超能力。</p></section><div class="badge-grid">${REWARDS.map(r=>{const value=vals[r.kind],unlocked=value>=r.need;return `<section class="panel badge-card ${unlocked?'unlocked':''}"><span class="badge-emblem">${ico(r.icon)}</span><span class="badge-state">${unlocked?'已点亮':'待解锁'}</span><h3>${r.title}</h3><p>${r.desc}</p><div class="mini-progress"><i style="width:${Math.min(100,value/r.need*100)}%"></i></div><small>${Math.min(value,r.need)} / ${r.need}</small></section>`;}).join('')}</div>`;}
function renderStats(main,s){const days=Array.from({length:35},(_,i)=>{const d=new Date();d.setDate(d.getDate()-34+i);return dayKey(d.getTime());});main.innerHTML=`${pageHeading('LOOK HOW FAR YOU HAVE COME','回头看，你已经走了这么远。','记录每一次探索，不和别人比较。')}<div class="stats-grid">${[[Object.keys(state.prog).length,'已学习的单词'],[s.mastered,'已掌握的单词'],[s.streak,'连续学习天数'],[`${s.today.acc}%`,'今日正确率']].map(([n,t])=>`<section class="panel stat-tile"><span>${t}</span><b>${n}</b></section>`).join('')}</div><section class="panel"><div class="section-title"><h2>最近 35 天的探索足迹</h2><span>每一格，都是你的一天</span></div><div class="activity-grid">${days.map(d=>`<div class="activity-cell ${(state.daily[d]?.totalN||0)>0?'lit':''}" title="${d}：${state.daily[d]?.totalN||0} 次练习"><span>${Number(d.slice(-2))}</span><small>${state.daily[d]?.totalN||'·'}</small></div>`).join('')}</div><p class="muted small">亮起的格子表示当天完成过学习。</p></section><section class="panel"><div class="section-title"><h2>记忆正在慢慢扎根</h2></div><div class="distribution"><span>尚未探索 <b>${s.fresh}</b></span><span>学习中 <b>${s.learning}</b></span><span>已掌握 <b>${s.mastered}</b></span></div><div class="mini-progress"><i style="width:${s.masteredPct}%"></i></div><p class="muted small">掌握需要多次间隔复习。今天见过，过几天还记得，才算真正熟悉。</p></section>`;}
function soundSettingsHTML(){const enabled=state.settings.soundEffects!==false,volume=Math.round((state.settings.soundVolume??.4)*100);return `<section class="panel"><h2>点击与答题音效</h2><p>宇宙版是轻电子音，可爱版是柔和铃音。正确、错误、翻卡和打字各有不同反馈。</p><div class="setting-row"><span>互动音效</span><button class="button secondary" data-act="sound-toggle" aria-pressed="${enabled}">${ico('sound')} ${enabled?'已开启':'已关闭'}</button></div><label class="setting-row" for="soundVolume"><span>音效音量 <output id="soundVolumeValue">${volume}%</output></span><input id="soundVolume" type="range" min="0" max="100" value="${volume}" aria-label="音效音量"></label><div class="backup-actions"><button class="button secondary" data-act="sound-preview" data-kind="correct" ${enabled?'':'disabled'}>试听答对音效</button><button class="button secondary" data-act="sound-preview" data-kind="wrong" ${enabled?'':'disabled'}>试听答错音效</button></div><p class="muted small">音效默认轻声播放，可随时关闭；单词朗读独立控制。设置会保存在本机。</p></section>`;}
function musicSettingsHTML(){const enabled=state.settings.backgroundMusic!==false,volume=Math.round((state.settings.musicVolume??.18)*100);return `<section class="panel"><h2>学习背景音乐</h2><p>宇宙版是轻盈电子氛围，可爱版是温暖轻音乐。跟随世界切换，轻声陪你学习。</p><div class="setting-row"><span>背景音乐</span><button class="button secondary" data-act="music-toggle" aria-pressed="${enabled}">${ico('music')} ${enabled?'已开启':'已关闭'}</button></div><label class="setting-row" for="musicVolume"><span>音乐音量 <output id="musicVolumeValue">${volume}%</output></span><input id="musicVolume" type="range" min="0" max="100" value="${volume}" aria-label="背景音乐音量"></label><p class="muted small">点击页面后开始播放；切到后台自动暂停。单词朗读时会自动降低音乐音量，音效和音乐可分别设置。Carefree / Cipher — Kevin MacLeod (incompetech.com)，CC BY 4.0。<a href="./MUSIC_CREDITS.txt" target="_blank" rel="noopener">音乐来源与授权</a></p></section>`;}
function renderSettings(main){main.innerHTML=`${pageHeading('MAKE IT YOUR OWN','你的节奏，你的世界。','调整目标、切换风格，把成长记录好好收起来。')}<div class="settings-grid">${musicSettingsHTML()}${soundSettingsHTML()}<section class="panel"><h2>外观风格</h2><p>随时换一个世界，词库和学习进度保持一致。</p><div class="settings-themes">${Object.values(THEMES).map(t=>`<button class="theme-setting ${state.theme===t.id?'chosen':''}" data-act="theme" data-theme="${t.id}">${ico(t.icon)}<span>${t.name}</span>${state.theme===t.id?ico('check'):''}</button>`).join('')}</div><div class="future-slot">${ico('plus')} 更多个性化风格 · 未来扩展</div></section><section class="panel"><h2>每日学习目标</h2><label class="setting-row">新词上限 <input type="number" id="dailyGoal" min="0" max="100" value="${state.settings.newPerDay}"></label><label class="setting-row">复习上限 <input type="number" id="reviewGoal" min="0" max="200" value="${state.settings.reviewPerDay}"></label><p class="muted small">每轮最多 10 个词。任务完成后，还可以做自由巩固。</p></section><section class="panel"><h2>换设备？带上你的进度。</h2><p>数据保存在当前设备的当前浏览器。更换设备、浏览器或清除网站数据前，先导出备份。</p><div class="backup-actions"><button class="button primary" data-act="export">${ico('download')} 导出完整备份</button><button class="button secondary" data-act="restore">${ico('upload')} 导入备份</button></div><p class="muted small">词库、积分、主题、学习进度一起迁移。两台设备不会自动实时同步。</p></section><section class="panel"><h2>离线和发音</h2><p id="offlineStatus">${navigator.serviceWorker?.controller?'页面已由离线缓存管理。':'联网首次加载后会缓存页面；缓存就绪后可离线使用。'}</p><p class="muted small">朗读由设备浏览器提供，声音与离线可用性取决于系统中安装的英语语音。</p><button class="button secondary" data-act="speak" data-word="Hello, explorer!">${ico('sound')} 试一下英语发音</button></section></div>`;}

function modal(html){$('#modalContent').innerHTML=`<button class="dialog-close" data-act="close" aria-label="关闭">${ico('close')}</button>${html}`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function newImport(){preview=null;modal(`<span class="eyebrow">YOUR OWN COLLECTION</span><h2>把课堂单词带进来。</h2><p>一行一个单词，英文和释义用空格或制表符分隔。</p><label class="field-label">词库名称<input id="bookName" maxlength="40" value="我的课堂单词"></label><label class="field-label">单词内容<textarea id="importText" placeholder="apple 苹果&#10;rabbit 兔子&#10;thank you 谢谢"></textarea></label><div class="backup-actions"><button class="button primary" data-act="preview">预览并检查 ${ico('arrow')}</button><button class="button secondary" data-act="upload">上传文件</button></div><p class="muted small">支持 Excel / CSV / TXT / JSON。文件仅在本机读取。</p>`);}
function rowsToWords(rows){const items=[],problems=[],seen=new Set();let duplicates=0;rows.forEach((row,index)=>{if(!row||!row.some(c=>String(c??'').trim()))return;let word=String(row[0]??'').trim(),meaning=String(row[1]??'').trim();if(index===0&&/^(word|英文|单词|英文单词)$/i.test(word))return;const parsed=parseLine(`${word} ${meaning}`);if(parsed.error||!meaning||word.length>48){problems.push(`第 ${index+1} 行：${parsed.error||'缺少释义或单词过长'}`);return;}const k=wordKey(word);if(seen.has(k)){duplicates++;return;}seen.add(k);items.push({word,meaning:meaning.slice(0,500),pos:'',phonetic:'',example:String(row[2]??'').slice(0,500)});});return {items,problems,duplicates};}
function parseText(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/);return rowsToWords(lines.map(line=>{if(line.includes('\t'))return line.split('\t');if(line.includes(',')){return window.XLSX.utils.sheet_to_json(window.XLSX.read(line,{type:'string',raw:true}).Sheets.Sheet1,{header:1,raw:false})[0]||[];}const m=line.trim().match(/^([A-Za-z][A-Za-z'’ -]*?)\s+((?:(?:n|v|adj|adv)\.\s*)?[\u3400-\u9fff].*)$/);if(m)return[m[1],m[2]];const r=parseLine(line);return r.word?[r.word,r.meaning]:[line,''];}));}
function showImportPreview(report,name){preview={...report,name:String(name||'我的单词').slice(0,40)};modal(`<span class="eyebrow">CHECK BEFORE IMPORT</span><h2>检查一下，再出发。</h2><p>「${esc(preview.name)}」：${report.items.length} 个可导入的词，${report.duplicates} 个重复，${report.problems.length} 行需要修改。</p>${report.problems.length?`<div class="import-problems">${report.problems.slice(0,12).map(esc).join('<br>')}</div>`:''}<div class="preview-table">${report.items.slice(0,30).map(w=>`<div><b>${esc(w.word)}</b><span>${esc(w.meaning)}</span></div>`).join('')}</div>${report.items.length>30?'<p class="muted small">此处预览前 30 个词，确认后导入全部有效单词。</p>':''}<div class="backup-actions"><button class="button primary" data-act="confirm-import" ${report.items.length?'':'disabled'}>确认导入 ${report.items.length} 个词</button><button class="button secondary" data-act="new">返回重新编辑</button></div>`);}
async function importFile(file){if(file.size>5*1024*1024){toast('请使用 5MB 以内的词库文件。');return;}try{let report;const ext=file.name.split('.').pop().toLowerCase();if(['xlsx','xls','csv','tsv'].includes(ext)){if(!window.XLSX)throw Error('表格读取组件尚未准备好，请稍后再试');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array',raw:true});const rows=XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{header:1,raw:false,defval:''});report=rowsToWords(rows);}else if(ext==='json'){const data=JSON.parse(await file.text());if(data.prog||data.daily){toast('这是完整备份，请到「偏好与备份」导入。');return;}const words=Array.isArray(data)?data:data.words;if(!Array.isArray(words))throw Error('JSON 应为单词数组或包含 words 数组');report=rowsToWords(words.map(w=>Array.isArray(w)?w:[w.word,w.meaning,w.example]));}else report=parseText(await file.text());if(report.items.length>10000)throw Error('每次最多导入 10000 个单词');showImportPreview(report,file.name.replace(/\.[^.]+$/,''));}catch(e){toast(`读取失败：${e.message}`);}}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let incomingBackup=null;
async function restoreFile(file){if(file.size>15*1024*1024){toast('备份文件过大，请检查是否选对文件。');return;}try{const p=JSON.parse(await file.text());if(!validBackup(p))throw Error('格式不正确');incomingBackup=p;modal(`<h2>恢复你的探索记录</h2><p>备份包含 ${p.books.length} 个词库、${p.words.length} 个单词。合并将保留当前内容；替换将覆盖本机记录。</p><div class="backup-actions"><button class="button primary" data-act="merge-backup">合并进来</button><button class="button secondary" data-act="replace-backup">替换本机记录</button></div>`);}catch{toast('备份无效，当前数据没有改变。');}}
function restore(replace){if(!incomingBackup||!validBackup(incomingBackup))return;if(replace){modal(`<h2>确认替换本机记录？</h2><p>当前设备上的词库和进度将被备份覆盖。需要保留的内容，请先取消并导出。</p><button class="button primary" data-act="replace-confirm">确认替换</button>`);return;}const p=incomingBackup;state={...state,...mergeStates(state,p),...mergeRewards(state,p),mistakes:mergeMistakes(state.mistakes,p.mistakes)};finishRestore();}
function finishRestore(){selectedMistakes=null;incomingBackup=null;session=null;view='home';save();closeModal();render();toast('备份已恢复。');}
function speak(word){if(!('speechSynthesis' in window)){toast('当前浏览器不支持朗读。');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(word);utterance.lang='en-US';utterance.rate=.82;const voice=speechSynthesis.getVoices().find(v=>v.lang==='en-US')||speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(voice)utterance.voice=voice;const finish=music.beginSpeech();utterance.onend=finish;utterance.onerror=e=>{finish();if(e.error!=='interrupted'&&e.error!=='canceled')toast('发音暂时不可用，请检查设备英语语音或网络。');};try{speechSynthesis.speak(utterance);}catch{finish();toast('发音暂时不可用，请检查设备英语语音或网络。');}}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-act]');if(!el)return;const {act,id}=el.dataset;e.preventDefault();if(syncExternal())return;
 if(!['theme','answer','choice','giveup','speak','spell-key','sound-toggle','sound-preview','music-toggle'].includes(act)){const cue=act==='reveal'?'flip':['start','quick','book-start','preset-start','again'].includes(act)?'start':['preset-add','confirm-import'].includes(act)?'reward':'click';sounds.play(cue);}
 if(act==='theme'){if(!THEMES[el.dataset.theme])return;state.theme=el.dataset.theme;save();sounds.play('switch');render();}
 else if(act==='music-toggle'){state.settings.backgroundMusic=state.settings.backgroundMusic===false;save();music.sync();render();}
 else if(act==='sound-toggle'){state.settings.soundEffects=state.settings.soundEffects===false;save();if(state.settings.soundEffects)sounds.play('click');else sounds.cancel();render();}
 else if(act==='sound-preview')sounds.play(el.dataset.kind);
 else if(act==='spell-key')editSpelling(el.dataset.key);
 else if(act==='nav'){if(session&&session.phase==='q'&&session.stats.total>0){modal(`<h2>稍后再继续？</h2><p>已完成的作答已经保存，剩下的单词下次可以继续学习。</p><button class="button primary" data-act="leave" data-view="${el.dataset.view}">离开本轮</button>`);return;}session=null;view=el.dataset.view;render();window.scrollTo(0,0);}
 else if(act==='leave'){session=null;view=el.dataset.view;closeModal();render();}
 else if(act==='close')closeModal();
 else if(act==='preset')showPreset(id);
 else if(act==='preset-add'){bookId=addPreset(id);view='book';closeModal();render();toast('已加入你的词库。');}
 else if(act==='preset-start'){const b=addPreset(id);start(null,b);}
 else if(act==='book'){bookId=id;view='book';render();}
 else if(act==='start')start();
 else if(act==='book-start')start(null,id);
 else if(act==='quick')start(el.dataset.mode);
 else if(act==='mistakes-start')startCorrections(el.dataset.mode);
 else if(act==='mistakes-all'){selectedMistakes=new Set(mistakeEntries().map(([key])=>key));render();}
 else if(act==='mistakes-none'){selectedMistakes=new Set();render();}
 else if(act==='reveal'){if(session){session.revealed=true;render();}}
 else if(act==='answer'){answer(el.dataset.result);next();}
 else if(act==='choice'){if(!session||session.phase!=='q')return;session.chosen=Number(el.dataset.index);answer(current().options[session.chosen]===current().meaning?'know':'forgot');}
 else if(act==='giveup')answer('forgot');
 else if(act==='next')next();
 else if(act==='exit'){modal(`<h2>结束这次探索？</h2><p>已经完成的练习和奖励已保存。休息一下，随时回来。</p><button class="button primary" data-act="finish">保存并回首页</button>`);}
 else if(act==='finish'){const correction=session?.correction;session=null;view=correction?'mistakes':'home';closeModal();render();}
 else if(act==='again'){const mode=session?.mode,book=session?.book,correction=session?.correction;session=null;if(correction)startCorrections(mode);else start(mode,book);}
 else if(act==='speak')speak(el.dataset.word);
 else if(act==='new')newImport();
 else if(act==='upload')$('#wordFile').click();
 else if(act==='preview')showImportPreview(parseText($('#importText').value),$('#bookName').value);
 else if(act==='confirm-import'){if(!preview?.items.length)return;const b={id:uid('b'),name:preview.name,on:true};state.books.push(b);state.words.push(...preview.items.map(w=>({...w,id:uid('w'),bookId:b.id})));save();bookId=b.id;preview=null;view='book';closeModal();render();toast('词库导入完成。');}
 else if(act==='template')download('\uFEFF英文单词,中文释义,例句\r\napple,苹果,I like apples.\r\nrabbit,兔子,The rabbit is white.\r\nthank you,谢谢,Thank you for your help.','单词探索站-词库模板.csv','text/csv;charset=utf-8');
 else if(act==='export'){state.lastExport=Date.now();save();download(JSON.stringify(state,null,2),`单词探索站-完整备份-${dayKey()}.json`);toast('备份已导出，请妥善保存。');}
 else if(act==='restore')$('#backupFile').click();
 else if(act==='merge-backup')restore(false);
 else if(act==='replace-backup')restore(true);
 else if(act==='replace-confirm'){if(!incomingBackup||!validBackup(incomingBackup))return;state={...blank(),...incomingBackup,settings:{...blank().settings,...incomingBackup.settings}};if(!THEMES[state.theme])state.theme=null;finishRestore();}
 else if(act==='rename'){const b=state.books.find(b=>b.id===id);modal(`<h2>为词库起个新名字</h2><form id="renameForm" data-id="${id}"><input id="renameInput" aria-label="词库名称" maxlength="40" value="${esc(b.name)}" required><button class="button primary" type="submit">保存</button></form>`);}
 else if(act==='delete'){const b=state.books.find(b=>b.id===id);modal(`<h2>删除「${esc(b.name)}」？</h2><p>这会删除词库中的单词，其他词库和累计奖励不受影响。</p><button class="button primary" data-act="delete-confirm" data-id="${id}">确认删除</button>`);}
 else if(act==='delete-confirm'){state.books=state.books.filter(b=>b.id!==id);state.words=state.words.filter(w=>w.bookId!==id);save();closeModal();view='books';render();}
});
document.addEventListener('submit',e=>{e.preventDefault();if(syncExternal())return;if(e.target.id==='spellForm'&&session?.phase==='q'){const value=$('#spelling').value;if(!value.trim()){sounds.play('gentle');toast('先试着拼写一下吧。');return;}session.input=value;answer(checkSpelling(value,current().word)?'know':'forgot');}if(e.target.id==='renameForm'){const name=$('#renameInput').value.trim();if(!name)return;const b=state.books.find(b=>b.id===e.target.dataset.id);if(b)b.name=name;save();closeModal();render();}});
document.addEventListener('change',e=>{if(syncExternal())return;if(e.target.dataset.mistakeKey){selectedMistakes??=new Set();if(e.target.checked)selectedMistakes.add(e.target.dataset.mistakeKey);else selectedMistakes.delete(e.target.dataset.mistakeKey);render();return;}if(e.target.id==='soundVolume'){state.settings.soundVolume=Math.max(0,Math.min(1,Number(e.target.value)/100));save();sounds.play('type');}if(e.target.id==='wordFile'&&e.target.files[0])importFile(e.target.files[0]);if(e.target.id==='backupFile'&&e.target.files[0])restoreFile(e.target.files[0]);if(['wordFile','backupFile'].includes(e.target.id))e.target.value='';if(['dailyGoal','reviewGoal'].includes(e.target.id)){const key=e.target.id==='dailyGoal'?'newPerDay':'reviewPerDay',max=key==='newPerDay'?100:200;state.settings[key]=Math.max(0,Math.min(max,parseInt(e.target.value)||0));e.target.value=state.settings[key];save();toast('目标已保存。');}});
document.addEventListener('keydown',e=>{if($('#modal').open||!session||e.isComposing||e.ctrlKey||e.metaKey||e.altKey)return;if(session.currentMode==='spell'&&session.phase==='q'){if(/^[a-z '-]$/i.test(e.key)||e.key==='Backspace'){e.preventDefault();editSpelling(e.key);return;}if(e.key==='Enter'){e.preventDefault();$('#spellForm')?.requestSubmit();return;}}if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(session.currentMode==='choice'&&session.phase==='q'&&/^[1-4]$/.test(e.key))$(`[data-act="choice"][data-index="${Number(e.key)-1}"]`)?.click();if(session.currentMode==='card'&&e.code==='Space'){e.preventDefault();if(!session.revealed){session.revealed=true;sounds.play('flip');render();}}});
document.addEventListener('input',e=>{if(e.target.id==='musicVolume'){if(syncExternal())return;state.settings.musicVolume=Math.max(0,Math.min(1,Number(e.target.value)/100));$('#musicVolumeValue').textContent=Math.round(state.settings.musicVolume*100)+'%';save();music.sync();}if(e.target.id==='soundVolume'){if(syncExternal())return;state.settings.soundVolume=Math.max(0,Math.min(1,Number(e.target.value)/100));$('#soundVolumeValue').textContent=Math.round(state.settings.soundVolume*100)+'%';if(state.settings.soundVolume===0)sounds.cancel();save();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
window.addEventListener('storage',e=>{if(e.key===STORAGE||e.key===null)syncExternal();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!session)render();});
load();render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').catch(()=>{});}
window.__orbit={get state(){return state;},get session(){return session;}};
